"""Build the public task-card catalog from the runnable specifications (no data needed)."""
from pathlib import Path
import json
import tomllib

ROOT = Path(__file__).resolve().parents[1]


def main():
    lines = [
        '# Task cards', '',
        'Generated by `python scripts/build_task_cards.py` from the committed task packages.',
        'Each task card links to its runnable specification, instructions and data manifest.',
        'Compiled input data are maintained separately from the task definitions.',
        'See [data provenance](DATA_SOURCES.md) and [data access](DATA_ACCESS.md).', '',
    ]
    tasks = sorted((ROOT / 'benchmarks/spatial_alignment/tasks').glob('*/task.toml'))
    lines.extend([f'{len(tasks)} benchmark tasks.', ''])
    for task in tasks:
        d = tomllib.loads(task.read_text())
        prefix = '../' + task.parent.relative_to(ROOT).as_posix()
        manifest = task.parent / 'data/manifest.json'
        m = json.loads(manifest.read_text())
        source = str(m.get('source', 'See data provenance')).replace('\n', ' ')
        lines.extend([
            f"## {d['id']}", '', f"**{d.get('name', d.get('title', d['id']))}**", '',
            f"- Type: `{d['task_type']}`; difficulty: `{d.get('difficulty', 'unspecified')}`.",
            f"- Input: `{d.get('input_contract', 'unspecified')}`; {len(d.get('slices', []))} slices.",
            f"- Output: `{d.get('output_contract', 'unspecified')}`.",
            f"- Scoring: `{d.get('metric_profile', 'unspecified')}`.",
            f'- Source (as recorded in the manifest): {source}.',
            f'- [Specification]({prefix}/task.toml) · [Instructions]({prefix}/instruction.md) · [Data manifest]({prefix}/data/manifest.json)', '',
        ])
    (ROOT / 'docs/TASK_CARDS.md').write_text('\n'.join(lines))


if __name__ == '__main__':
    main()
